    results[name] = self.daily_incident_cases
elif name in ("infections_averted", "cumulative_infections_averted"):
    results[name] = self.cumulative_infections_averted
elif name == "masks_purchased":
    results[name] = getattr(self, "cumulative_masks_purchased", 0)
elif name == "subgroup_adoption_gap":
    # top vs bottom income quintile at final day
    incomes = sorted([p.income for p in self.people])
    quint = [incomes[int(len(incomes) * q / 5)] for q in range(1, 5)] if incomes else []
    groups = {i: [] for i in range(5)}
    for idx, p in enumerate(self.people):
        g = 0
        while g < 4 and p.income > quint[g]: g += 1
        groups[g].append(1.0 if p.mask_adoption_state == "wearing" else 0.0)
    top = sum(groups[4]) / len(groups[4]) if groups[4] else 0.0
    bottom = sum(groups[0]) / len(groups[0]) if groups[0] else 0.0
    results[name] = top - bottom
